insert into public.testimonials (name, city, product, rating_taste, rating_quality, rating_service, review, consent, is_approved, is_sample, created_at) values ('Rina Kartikasari', 'Tembalang', 'Kunir Asem', 5, 5, 5, 'Kunir asemnya seger banget, asamnya pas dan nggak bikin enek. Sekarang jadi stok wajib di kulkas kos tiap minggu.', true, true, true, '2026-10-28'::timestamptz);
insert into public.testimonials (name, city, product, rating_taste, rating_quality, rating_service, review, consent, is_approved, is_sample, created_at) values ('Bagus Prasetyo', 'Banyumanik', 'Jahe Merah', 5, 5, 4, 'Pulang kerja malam badan rasanya capek, minum jahe merah hangat langsung enakan. Pesan lewat ojol juga cepat sampai.', true, true, true, '2026-10-21'::timestamptz);
insert into public.testimonials (name, city, product, rating_taste, rating_quality, rating_service, review, consent, is_approved, is_sample, created_at) values ('Endang Suharti', 'Gajahmungkur', 'Beras Kencur', 5, 5, 5, 'Dari zaman Bu Ranti masih keliling gendong saya sudah langganan. Rasanya tetap sama, cuma sekarang botolnya lebih bagus.', true, true, true, '2026-10-15'::timestamptz);
insert into public.testimonials (name, city, product, rating_taste, rating_quality, rating_service, review, consent, is_approved, is_sample, created_at) values ('Nadia Rahmawati', 'Candisari', 'Sereh Telang', 4, 5, 5, 'Warnanya biru cantik, wangi serehnya lembut. Awalnya beli karena penasaran buat difoto, eh ternyata enak dan jadi repeat order.', true, true, true, '2026-10-09'::timestamptz);
insert into public.testimonials (name, city, product, rating_taste, rating_quality, rating_service, review, consent, is_approved, is_sample, created_at) values ('Fajar Nugroho', 'Pedurungan', 'Temulawak', 4, 5, 5, 'Saya kira bakal pahit banget, ternyata masih enak diminum dingin. Adminnya ramah dan fast respon di WhatsApp.', true, true, true, '2026-09-30'::timestamptz);
insert into public.testimonials (name, city, product, rating_taste, rating_quality, rating_service, review, consent, is_approved, is_sample, created_at) values ('Ayu Wulandari', 'Ngaliyan', 'Paket Hampers', 5, 5, 5, 'Pesan hampers buat hantaran keluarga, kemasannya rapi dan kelihatan premium. Banyak yang tanya belinya di mana.', true, true, true, '2026-09-18'::timestamptz);
insert into public.testimonials (name, city, product, rating_taste, rating_quality, rating_service, review, consent, is_approved, is_sample, created_at) values ('Hendra Wijaya', 'Semarang Barat', 'Pegel Linu', 4, 4, 5, 'Rutin beli buat bapak saya yang suka pegal habis berkebun. Katanya rasanya mirip jamu langganan zaman dulu.', true, true, true, '2026-09-05'::timestamptz);
insert into public.testimonials (name, city, product, rating_taste, rating_quality, rating_service, review, consent, is_approved, is_sample, created_at) values ('Putri Anggraeni', 'Tlogosari', 'Rosella', 5, 4, 5, 'Rosellanya asam segar, cocok diminum siang-siang. Harganya juga ramah kantong mahasiswa.', true, true, true, '2026-08-27'::timestamptz);
